{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "The ketoprofen-glucose prodrug, the highest-transfer analogue, showed transporter-mediated brain uptake in situ in rats and was classified as BBB-permeable, indicating that a glucose-containing molecule can achieve meaningful CNS access despite a polar sugar moiety.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Abiraterone, a lipophilic steroidal molecule with a heteroaromatic substituent, reached brain concentrations five- to nine-fold higher than blood in rats, supporting CNS penetration of lipophilic fused-ring terpenoid scaffolds similar to the query's diterpene core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Liquiritin, a glycosylated natural product, was detected in rat brain tissue, directly demonstrating that glycosides can cross the blood-brain barrier and supporting the query's glycoside-containing structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Dictyostatin, a complex macrocyclic natural product, showed good brain penetration in mice with a brain AUC of 6245 nM·h, indicating that large, polar-featured natural products can still achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A cembranoid diterpene was detected in rat brain after intravenous administration and modulated CNS-regulated behavior, providing direct evidence that diterpenoid natural products can cross the BBB after systemic dosing.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental evidence consistently supports meaningful CNS access for the query glycosylated diterpene aldehyde. Direct measurements on glycosides, steroidal terpenoids, and diterpenoid natural products show that the polar sugar does not preclude BBB penetration, and transporter-mediated uptake can provide adequate CNS exposure.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement is available for the exact query molecule.",
    "The specific transporter involvement or efflux liability of the query is not experimentally defined.",
    "Human CNS exposure data are absent, so translation from rodent and in situ models is inferred."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

